def fit(A, y):
    b = np.linalg.lstsq(A, y, rcond=None)[0]
    w = np.ones(len(y))
    for _ in range(25):
        e = np.linalg.norm(A @ b - y, axis=1)
        w = 1 / (1 + (e / max(2 * np.median(e), 1e-09)) ** 2)
        t = np.sqrt(w)
        b = np.linalg.lstsq(t[:, None] * A, t[:, None] * y, rcond=None)[0]
    return (b, w)

def design(x, j, kind='cyclic'):
    from itertools import combinations_with_replacement
    (a, b) = (x[:, j], x[:, (j + 1) % 4])
    terms = [np.ones(len(x)), *x.T, a * b, a ** 3]
    if kind == 'cubic':
        terms = [np.ones(len(x))] + [np.prod(x[:, ii], axis=1) for p in (1, 2, 3) for ii in combinations_with_replacement(range(4), p)]
    return np.column_stack(terms)

def _bridge(cal):
    raw = np.asarray(cal['bridge_raw'])
    loads = np.asarray(cal['true_channel_loads'])
    return np.linalg.lstsq(np.column_stack((raw, np.ones(len(raw)))), loads, rcond=None)[0].sum(axis=1)

def _design(taus, past, hold, x, dt, t):
    a = np.exp(-dt[:, None] / taus)
    b = -np.expm1(-dt[:, None] / taus)
    z = np.zeros((len(hold), 2))
    for s in range(len(dt)):
        z = a[s] * z + b[s] * past[:, s, None]
    gap = hold[:, None] - z
    drift = np.column_stack((np.ones(len(x)), x))
    curve = np.concatenate((gap[:, None, :] * -np.expm1(-t[:, None] / taus), t[None, :, None] * drift[:, None, :]), axis=2)
    return (curve, np.column_stack((gap / taus, drift)))
